// workers/sessionCorsWorker/fetchRequestNormalization.js
var normalizeFetchTargetUrl = ({ url, deps } = {}) => {
  const input = toTrimmedString2(url);
  if (!input) {
    return {
      ok: false,
      status: 400,
      error: "Missing url",
      targetUrl: ""
    };
  }
  let target = null;
  try {
    target = new URL(input);
  } catch {
    return {
      ok: false,
      status: 400,
      error: "Invalid URL",
      targetUrl: ""
    };
  }
  if (!/^https?:$/.test(target.protocol)) {
    return {
      ok: false,
      status: 400,
      error: "URL must be http(s)",
      targetUrl: target.toString()
    };
  }
  if (deps?.isBlockedOutboundUrl?.(target.toString())) {
    return {
      ok: false,
      status: 403,
      error: "URL target is not allowed",
      targetUrl: target.toString()
    };
  }
  return {
    ok: true,
    status: 200,
    error: "",
    targetUrl: target.toString()
  };
};

// workers/sessionCorsWorker/fetchExecution.js
var FETCH_CACHE_TTL_SECONDS = 3600;
var FETCH_USER_AGENT = "ContextEngineSessionCorsWorker";
var MAX_RESPONSE_BYTES = 10 * 1024 * 1024;
var resolveJson3 = (deps) => deps?.json || json;
var resolveNormalizedTarget = ({ url, deps } = {}) => (deps?.normalizeFetchTargetUrl || normalizeFetchTargetUrl)({
  url,
  deps: {
    isBlockedOutboundUrl: deps?.isBlockedOutboundUrl
  }
});
var fetchNormalizedTarget = async ({
  url,
  baseHeaders,
  deps
} = {}) => {
  const json2 = resolveJson3(deps);
  const normalized = resolveNormalizedTarget({ url, deps });
  if (!normalized?.ok) {
    return {
      ok: false,
      response: json2({ error: normalized?.error }, normalized?.status || 400, baseHeaders)
    };
  }
  const response2 = await deps?.safeFetch?.(normalized.targetUrl, {
    headers: { "user-agent": FETCH_USER_AGENT },
    cf: { cacheTtl: FETCH_CACHE_TTL_SECONDS }
  });
  if (!(response2 instanceof Response)) {
    return {
      ok: false,
      response: json2({ error: response2?.error }, response2?.status, baseHeaders)
    };
  }
  return {
    ok: true,
    response: response2,
    json: json2
  };
};
var parseContentLength = (response2) => parseInt(response2?.headers?.get?.("content-length") || "0", 10);
var stripHtml = (html) => String(html || "").replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "").replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, "").replace(/<head\b[^<]*(?:(?!<\/head>)<[^<]*)*<\/head>/gi, "").replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, "").replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
var fetchImage = async ({
  url,
  baseHeaders,
  deps
} = {}) => {
  const fetchResult = await fetchNormalizedTarget({ url, baseHeaders, deps });
  if (!fetchResult?.ok) return fetchResult?.response;
  const { response: response2, json: json2 } = fetchResult;
  const contentLength = parseContentLength(response2);
  if (contentLength > MAX_RESPONSE_BYTES) {
    return json2({ error: "Response too large" }, 413, baseHeaders);
  }
  if (!response2.ok) {
    return json2({ error: `HTTP ${response2.status}` }, 400, baseHeaders);
  }
  const type = response2.headers.get("content-type") || "";
  if (!type.startsWith("image/")) {
    return json2({ error: "URL must return an image" }, 400, baseHeaders);
  }
  const headers = new Headers(baseHeaders);
  headers.set("Content-Type", type);
  return new Response(response2.body, { status: 200, headers });
};
var fetchUrl = async ({
  url,
  baseHeaders,
  deps
} = {}) => {
  const fetchResult = await fetchNormalizedTarget({ url, baseHeaders, deps });
  if (!fetchResult?.ok) return fetchResult?.response;
  const { response: response2, json: json2 } = fetchResult;
  const contentLength = parseContentLength(response2);
  if (contentLength > MAX_RESPONSE_BYTES) {
    return json2({ error: "Response too large" }, 413, baseHeaders);
  }
  if (!response2.ok) {
    return json2({ error: `HTTP ${response2.status}` }, 400, baseHeaders);
  }
  const type = response2.headers.get("content-type") || "";
  if (!/text\/html|application\/json/i.test(type)) {
    return json2({ error: "URL must return HTML or JSON" }, 400, baseHeaders);
  }
  if (type.includes("application/json")) {
    const data = await response2.json();
    return json2({ content: JSON.stringify(data), status: "success", contentType: type }, 200, baseHeaders);
  }
  const stripped = stripHtml(await response2.text());
  if (!stripped || stripped.length < 50) {
    return json2({ error: "Insufficient content extracted" }, 400, baseHeaders);
  }
  return json2({ content: stripped, status: "success", contentType: type }, 200, baseHeaders);
};

